namespace MapStudio.Core.IO;

public sealed record PendingFileWrite(
    string TargetPath,
    string BackupPath,
    byte[] Bytes);

namespace MapStudio.Core.IO;

public static class SafeFileTransaction
{
    public static async Task WriteAllAsync(
        IReadOnlyList<PendingFileWrite> writes,
        CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(writes);

        if (writes.Count == 0)
        {
            return;
        }

        var normalizedTargets =
            new HashSet<string>(
                StringComparer.OrdinalIgnoreCase);

        foreach (var write in writes)
        {
            ArgumentException.ThrowIfNullOrWhiteSpace(
                write.TargetPath);

            ArgumentException.ThrowIfNullOrWhiteSpace(
                write.BackupPath);

            var target =
                Path.GetFullPath(
                    write.TargetPath);

            if (
                !normalizedTargets.Add(
                    target))
            {
                throw new InvalidOperationException(
                    "duplicateTarget");
            }

            if (!File.Exists(target))
            {
                throw new FileNotFoundException(
                    "Target file does not exist.",
                    target);
            }
        }

        var staged =
            new List<(
                PendingFileWrite Write,
                string TempPath)>(
                    writes.Count);

        var replaced =
            new List<PendingFileWrite>(
                writes.Count);

        try
        {
            foreach (var write in writes)
            {
                cancellationToken
                    .ThrowIfCancellationRequested();

                var target =
                    Path.GetFullPath(
                        write.TargetPath);

                var targetDirectory =
                    Path.GetDirectoryName(
                        target) ??
                    throw new InvalidOperationException(
                        "targetDirectoryMissing");

                var backup =
                    Path.GetFullPath(
                        write.BackupPath);

                var backupDirectory =
                    Path.GetDirectoryName(
                        backup) ??
                    throw new InvalidOperationException(
                        "backupDirectoryMissing");

                Directory.CreateDirectory(
                    backupDirectory);

                File.Copy(
                    target,
                    backup,
                    overwrite: false);

                var tempPath =
                    Path.Combine(
                        targetDirectory,
                        $".{Path.GetFileName(target)}.mapstudio-{Guid.NewGuid():N}.tmp");

                await File.WriteAllBytesAsync(
                    tempPath,
                    write.Bytes,
                    cancellationToken);

                staged.Add((
                    write,
                    tempPath));
            }

            foreach (var item in staged)
            {
                cancellationToken
                    .ThrowIfCancellationRequested();

                File.Replace(
                    item.TempPath,
                    item.Write.TargetPath,
                    destinationBackupFileName: null,
                    ignoreMetadataErrors: true);

                replaced.Add(
                    item.Write);
            }
        }
        catch
        {
            foreach (var write in
                replaced.AsEnumerable()
                    .Reverse())
            {
                try
                {
                    File.Copy(
                        write.BackupPath,
                        write.TargetPath,
                        overwrite: true);
                }
                catch
                {
                    // Keep the original exception.
                    // Backup remains available.
                }
            }

            throw;
        }
        finally
        {
            foreach (var item in staged)
            {
                try
                {
                    if (File.Exists(
                            item.TempPath))
                    {
                        File.Delete(
                            item.TempPath);
                    }
                }
                catch
                {
                    // Best effort temp cleanup.
                }
            }
        }
    }
}

using System.Text;

namespace MapStudio.Core.Omsi.Config;

public sealed class OmsiConfigDocument
{
    public OmsiConfigDocument(
        IReadOnlyList<string> lines,
        IReadOnlyList<OmsiConfigSection> sections,
        string newLine,
        bool hasTrailingNewLine,
        Encoding textEncoding,
        bool hasByteOrderMark)
    {
        Lines = lines;
        Sections = sections;
        NewLine = newLine;
        HasTrailingNewLine = hasTrailingNewLine;
        TextEncoding = textEncoding;
        HasByteOrderMark = hasByteOrderMark;
    }

    public IReadOnlyList<string> Lines { get; }
    public IReadOnlyList<OmsiConfigSection> Sections { get; }
    public string NewLine { get; }
    public bool HasTrailingNewLine { get; }
    public Encoding TextEncoding { get; }
    public bool HasByteOrderMark { get; }

    public IEnumerable<OmsiConfigSection> FindSections(string keyword) =>
        Sections.Where(section =>
            string.Equals(section.Keyword, keyword, StringComparison.OrdinalIgnoreCase));

    public OmsiConfigSection? FindFirstSection(string keyword) =>
        FindSections(keyword).FirstOrDefault();

    public string ToText()
    {
        var text = string.Join(NewLine, Lines);
        return HasTrailingNewLine && Lines.Count > 0 ? text + NewLine : text;
    }

    public byte[] ToBytes()
    {
        var content = TextEncoding.GetBytes(ToText());

        if (!HasByteOrderMark)
        {
            return content;
        }

        var preamble = TextEncoding.GetPreamble();

        if (preamble.Length == 0)
        {
            return content;
        }

        var result = new byte[preamble.Length + content.Length];
        Buffer.BlockCopy(preamble, 0, result, 0, preamble.Length);
        Buffer.BlockCopy(content, 0, result, preamble.Length, content.Length);
        return result;
    }
}

using System.Text;

namespace MapStudio.Core.Omsi.Config;

public static class OmsiConfigParser
{
    private static readonly UTF8Encoding StrictUtf8 = new(
        encoderShouldEmitUTF8Identifier: false,
        throwOnInvalidBytes: true);

    static OmsiConfigParser()
    {
        Encoding.RegisterProvider(CodePagesEncodingProvider.Instance);
    }

    public static OmsiConfigDocument Parse(string text)
    {
        ArgumentNullException.ThrowIfNull(text);
        return ParseText(text, new UTF8Encoding(false), hasByteOrderMark: false);
    }

    public static OmsiConfigDocument ParseBytes(ReadOnlySpan<byte> bytes)
    {
        var (encoding, hasBom, preambleLength) = DetectEncoding(bytes);
        var text = encoding.GetString(bytes[preambleLength..]);
        return ParseText(text, encoding, hasBom);
    }

    public static async Task<OmsiConfigDocument> ParseFileAsync(
        string path,
        CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(path);
        var bytes = await File.ReadAllBytesAsync(path, cancellationToken);
        return ParseBytes(bytes);
    }

    private static OmsiConfigDocument ParseText(
        string text,
        Encoding encoding,
        bool hasByteOrderMark)
    {
        var newLine = text.Contains("\r\n", StringComparison.Ordinal) ? "\r\n" : "\n";
        var hasTrailingNewLine =
            text.EndsWith("\r\n", StringComparison.Ordinal) ||
            text.EndsWith("\n", StringComparison.Ordinal);

        var lines = text
            .Replace("\r\n", "\n", StringComparison.Ordinal)
            .Split('\n')
            .ToList();

        if (hasTrailingNewLine && lines.Count > 0 && lines[^1].Length == 0)
        {
            lines.RemoveAt(lines.Count - 1);
        }

        var keywords = new List<(int Index, string Keyword)>();

        for (var index = 0; index < lines.Count; index++)
        {
            var value = lines[index].Trim();

            if (value.Length >= 3 &&
                value[0] == '[' &&
                value[^1] == ']' &&
                value.IndexOf(']') == value.Length - 1)
            {
                keywords.Add((index, value[1..^1]));
            }
        }

        var sections = new List<OmsiConfigSection>();

        for (var index = 0; index < keywords.Count; index++)
        {
            var current = keywords[index];
            var bodyStart = current.Index + 1;
            var bodyEnd = index + 1 < keywords.Count ? keywords[index + 1].Index : lines.Count;

            sections.Add(new OmsiConfigSection(
                current.Keyword,
                current.Index,
                lines.Skip(bodyStart).Take(bodyEnd - bodyStart).ToArray()));
        }

        return new OmsiConfigDocument(
            lines,
            sections,
            newLine,
            hasTrailingNewLine,
            encoding,
            hasByteOrderMark);
    }

    private static (Encoding Encoding, bool HasBom, int PreambleLength) DetectEncoding(
        ReadOnlySpan<byte> bytes)
    {
        if (bytes.StartsWith(new byte[] { 0xEF, 0xBB, 0xBF }))
        {
            return (new UTF8Encoding(true, true), true, 3);
        }

        if (bytes.StartsWith(new byte[] { 0xFF, 0xFE }))
        {
            return (new UnicodeEncoding(false, true, true), true, 2);
        }

        if (bytes.StartsWith(new byte[] { 0xFE, 0xFF }))
        {
            return (new UnicodeEncoding(true, true, true), true, 2);
        }

        try
        {
            _ = StrictUtf8.GetString(bytes);
            return (new UTF8Encoding(false, true), false, 0);
        }
        catch (DecoderFallbackException)
        {
            return (
                Encoding.GetEncoding(
                    1252,
                    EncoderFallback.ExceptionFallback,
                    DecoderFallback.ExceptionFallback),
                false,
                0);
        }
    }
}

namespace MapStudio.Core.Omsi.Config;

public sealed record OmsiConfigSection(
    string Keyword,
    int KeywordLineIndex,
    IReadOnlyList<string> RawBodyLines)
{
    public IEnumerable<string> DataLines =>
        RawBodyLines
            .Select(static line => line.Trim())
            .Where(static line => line.Length > 0 && !line.StartsWith('#'));
}

using System.Collections.Concurrent;
using System.Globalization;
using MapStudio.Core.Omsi.Config;

namespace MapStudio.Core.Omsi.Maps;

public sealed class OmsiMapCatalog
{
    private const int MaxConcurrentGlobalReads = 4;
    private static readonly TimeSpan PerMapTimeout =
        TimeSpan.FromSeconds(20);

    public async Task<IReadOnlyList<OmsiMapDescriptor>> DiscoverAsync(
        string omsiRoot,
        CancellationToken cancellationToken = default) =>
        (await DiscoverWithProgressAsync(
            omsiRoot,
            progress: null,
            cancellationToken)).Maps;

    public async Task<OmsiMapCatalogResult> DiscoverWithProgressAsync(
        string omsiRoot,
        IProgress<OmsiMapDiscoveryProgress>? progress = null,
        CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(omsiRoot);

        var mapsDirectory = Path.Combine(omsiRoot, "maps");

        if (!Directory.Exists(mapsDirectory))
        {
            return new OmsiMapCatalogResult(
                Array.Empty<OmsiMapDescriptor>(),
                SkippedMaps: 0);
        }

        var directories = Directory
            .EnumerateDirectories(mapsDirectory)
            .Where(directory =>
                File.Exists(
                    Path.Combine(
                        directory,
                        "global.cfg")))
            .OrderBy(static path => path)
            .Select((path, index) =>
                new
                {
                    Path = path,
                    Index = index
                })
            .ToArray();

        if (directories.Length == 0)
        {
            progress?.Report(
                new OmsiMapDiscoveryProgress(
                    Completed: 0,
                    Total: 0,
                    Skipped: 0,
                    DirectoryName: null));

            return new OmsiMapCatalogResult(
                Array.Empty<OmsiMapDescriptor>(),
                SkippedMaps: 0);
        }

        var results =
            new ConcurrentDictionary<int, OmsiMapDescriptor>();

        var completed = 0;
        var skipped = 0;

        await Parallel.ForEachAsync(
            directories,
            new ParallelOptions
            {
                CancellationToken = cancellationToken,
                MaxDegreeOfParallelism =
                    Math.Min(
                        MaxConcurrentGlobalReads,
                        Math.Max(
                            1,
                            Environment.ProcessorCount))
            },
            async (entry, token) =>
            {
                var directoryName =
                    Path.GetFileName(entry.Path);

                try
                {
                    using var timeout =
                        CancellationTokenSource
                            .CreateLinkedTokenSource(token);

                    timeout.CancelAfter(
                        PerMapTimeout);

                    var descriptor =
                        await ReadDescriptorAsync(
                            entry.Path,
                            timeout.Token);

                    results[entry.Index] =
                        descriptor;
                }
                catch (OperationCanceledException)
                    when (!token.IsCancellationRequested)
                {
                    Interlocked.Increment(
                        ref skipped);
                }
                catch (Exception exception)
                    when (IsRecoverableMapError(
                        exception))
                {
                    Interlocked.Increment(
                        ref skipped);
                }
                finally
                {
                    var current =
                        Interlocked.Increment(
                            ref completed);

                    progress?.Report(
                        new OmsiMapDiscoveryProgress(
                            Completed: current,
                            Total: directories.Length,
                            Skipped: Volatile.Read(
                                ref skipped),
                            DirectoryName:
                                directoryName));
                }
            });

        return new OmsiMapCatalogResult(
            results
                .OrderBy(pair => pair.Key)
                .Select(pair => pair.Value)
                .ToArray(),
            SkippedMaps:
                Volatile.Read(ref skipped));
    }

    public static async Task<OmsiMapDescriptor> OpenMapAsync(
        string directory,
        CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(directory);

        var fullDirectory =
            Path.GetFullPath(directory);

        var globalConfigPath =
            Path.Combine(
                fullDirectory,
                "global.cfg");

        if (!File.Exists(globalConfigPath))
        {
            throw new FileNotFoundException(
                "The selected map does not contain global.cfg.",
                globalConfigPath);
        }

        return await ReadDescriptorAsync(
            fullDirectory,
            cancellationToken);
    }

    private static async Task<OmsiMapDescriptor> ReadDescriptorAsync(
        string directory,
        CancellationToken cancellationToken)
    {
        var globalConfigPath = Path.Combine(
            directory,
            "global.cfg");

        var document =
            await OmsiConfigParser.ParseFileAsync(
                globalConfigPath,
                cancellationToken);

        var directoryName =
            Path.GetFileName(directory);

        var displayName =
            document
                .FindFirstSection("name")
                ?.DataLines
                .FirstOrDefault()
            ?? directoryName;

        return new OmsiMapDescriptor(
            directoryName,
            displayName,
            directory,
            globalConfigPath,
            UsesWorldCoordinates(document),
            ReadTiles(document));
    }

    private static bool IsRecoverableMapError(
        Exception exception) =>
        exception is IOException or
        UnauthorizedAccessException or
        ArgumentException or
        NotSupportedException;

    public static bool UsesWorldCoordinates(
        OmsiConfigDocument document)
    {
        ArgumentNullException.ThrowIfNull(document);

        return document.FindFirstSection(
            "worldcoordinates") is not null;
    }

    public static IReadOnlyList<OmsiTileReference> ReadTiles(
        OmsiConfigDocument document)
    {
        ArgumentNullException.ThrowIfNull(document);

        var tiles = new List<OmsiTileReference>();

        foreach (var section in document.FindSections("map"))
        {
            var values =
                section.DataLines
                    .Take(3)
                    .ToArray();

            if (values.Length < 3 ||
                !int.TryParse(
                    values[0],
                    NumberStyles.Integer,
                    CultureInfo.InvariantCulture,
                    out var x) ||
                !int.TryParse(
                    values[1],
                    NumberStyles.Integer,
                    CultureInfo.InvariantCulture,
                    out var y))
            {
                continue;
            }

            tiles.Add(new OmsiTileReference(
                x,
                y,
                values[2]));
        }

        return tiles;
    }
}

